package __PACKAGE__;

import java.util.ArrayList;
import java.util.List;
import java.util.Locale;
import java.util.Map;

/**
 * A Sparkle system read from its file: its emitters and its user parameters (by name, in lower case).
 * Generated by the Sparkle plugin: do not edit, it is written again when the runtime is updated.
 */
public record SparkleSystem(List<SparkleEmitter> emitters, Map<String, Parameter> parameters) {
    /** A setting of an emitter bound to a user parameter. */
    public record Binding(int emitter, String module, String key) {
    }

    /** A user parameter and the settings it changes. */
    public record Parameter(String name, List<Binding> bindings) {
    }

    /** Copies of the emitters with the values of the user parameters sent by the server. */
    public List<SparkleEmitter> instantiate(List<SparkleOptions.Parameter> values) {
        List<SparkleEmitter> copies = new ArrayList<>(emitters.size());
        for (SparkleEmitter emitter : emitters) {
            copies.add(emitter.copy());
        }

        for (SparkleOptions.Parameter value : values) {
            Parameter parameter = parameters.get(value.name().toLowerCase(Locale.ROOT));
            if (parameter == null) {
                continue;
            }

            for (Binding binding : parameter.bindings()) {
                SparkleEmitter emitter = copies.get(binding.emitter());
                emitter.setValue(binding.module(), binding.key(), value.x(), value.y(), value.z());
                emitter.finish();
            }
        }

        return copies;
    }
}
